"""## 8. English table (translated by the local model) + CSV"""

import json, pandas as pd
from IPython.display import display
import utils, app_config
def to_en(items):
    text = json.dumps(items, ensure_ascii=False)
    out = utils.call_llm_api(
        'You are a precise Chinese-to-English medical translator. Return ONLY a JSON object with the same keys; '
        'translate every Chinese value to concise English medical terms; keep lists as lists; keep numbers.',
        text)
    data = utils.parse_json_from_response(out)
    return data if isinstance(data, dict) else items

def fmt(v):
    if isinstance(v, list): return ', '.join(map(str, v)) if v else '-'
    return v if v not in (None, '') else '-'

rows = []
for l in logs:
    if 'error' in l: continue
    e = l['evaluations']
    raw = {
        'case': str(l['id']).split('_', 1)[-1],
        'dept_pred': [e['task1']['pred_l1']] + list(e['task1']['pred_l2']),
        'dept_true': [e['task1']['gt_l1']] + list(e['task1']['gt_l2']),
        'diag_pred': e['task4']['pred'], 'diag_true': e['task4']['gt'],
        'treat_pred': e['task5']['pred'], 'treat_true': e['task5']['gt'],
    }
    en = to_en(raw)
    rows.append({
        'Case': fmt(en.get('case', raw['case'])),
        'Dept (pred)': ' > '.join(map(str, en.get('dept_pred', raw['dept_pred']) or [])) or '-',
        'Dept (true)': ' > '.join(map(str, en.get('dept_true', raw['dept_true']) or [])) or '-',
        'L1 correct': 'yes' if e['task1']['l1_accuracy'] == 1.0 else 'no',
        'Diagnosis (pred)': fmt(en.get('diag_pred', raw['diag_pred'])),
        'Diagnosis (true)': fmt(en.get('diag_true', raw['diag_true'])),
        'Judge 1-5': e['task4']['raw_score'],
        'Treatment (pred)': fmt(en.get('treat_pred', raw['treat_pred'])),
        'Treatment (true)': fmt(en.get('treat_true', raw['treat_true'])),
        'Treatment IoU': None if e['task5']['treatment_iou'] is None else round(e['task5']['treatment_iou'], 2),
    })
df = pd.DataFrame(rows)
pd.set_option('display.max_colwidth', 80)
display(df)

m = [l['metrics'] for l in logs if 'metrics' in l]
def avg(k):
    v = [x[k] for x in m if x.get(k) is not None]
    return round(sum(v) / len(v), 3) if v else None
summary = pd.DataFrame([
    ['Task 1 Department L1', 'Accuracy', avg('t1_acc')],
    ['Task 1 Sub-department L2', 'IoU', avg('t1_iou')],
    ['Task 2 Exam planning', 'IoU', avg('t2_iou')],
    ['Task 3 Imaging report', 'DocLens', avg('t3_score')],
    ['Task 4 Diagnosis', 'Judge / 5', avg('t4_score')],
    ['Task 5 Treatment', 'IoU', avg('t5_iou')],
    ['Average', '', avg('paper_average')],
], columns=['Task', 'Metric', 'Score'])
display(summary)
df.to_csv('benchmark_results_english.csv', index=False, encoding='utf-8-sig')
summary.to_csv('benchmark_summary.csv', index=False, encoding='utf-8-sig')
print('saved benchmark_results_english.csv, benchmark_summary.csv')

