# --- this study's row from benchmark_results.json ---
logs = json.load(open(RESULTS))
ok = [l["metrics"] for l in logs if "metrics" in l and "error" not in l]
assert ok, "No successful cases in benchmark_results.json - run the benchmark first"
assert not any(str(l.get("id")) == "test_1" for l in logs), "These are smoke-test results, not a real run"
def avg(k):
    v = [m[k] for m in ok if m.get(k) is not None]
    return sum(v) / len(v) if v else None
ours = [avg(k) for k in COLS]
groups = PAPER + [(f"This study (n={len(ok)})", [(OUR_LABEL, ours)])]

# bold = best among published methods only (a 5-case pilot is not a fair contest)
best = []
for j in range(len(COLS)):
    vals = [r[1][j] for _, rows in PAPER for r in rows if r[1][j] is not None]
    best.append(max(vals))
fmt = lambda v: "—" if v is None else f"{v:.4f}"

# ------------------------------------------------------------------ PNG
n_rows = sum(len(r) for _, r in groups)
row_h, top_h = 0.26, 0.95
H = top_h + row_h * n_rows + 0.25 * len(groups) + 0.3
fig = plt.figure(figsize=(11, H), dpi=200)
ax = fig.add_axes([0, 0, 1, 1]); ax.set_xlim(0, 11); ax.set_ylim(H, 0); ax.axis("off")
plt.rcParams["font.family"] = "DejaVu Serif"
X_CAT, X_METH = 0.15, 1.65
XS = [4.35, 5.15, 6.15, 7.15, 8.1, 9.0, 10.15]          # column centres
L, R = 0.1, 10.9
def hline(y, lw, x0=L, x1=R): ax.plot([x0, x1], [y, y], color="black", lw=lw)
def txt(x, y, s, bold=False, ha="center", size=9, italic=False):
    ax.text(x, y, s, ha=ha, va="center", fontsize=size, fontweight="bold" if bold else "normal",
            style="italic" if italic else "normal")

y = 0.15; hline(y, 1.4)                                   # toprule
txt((XS[0] + XS[5]) / 2, y + 0.2, "MedChain", bold=True)
hline(y + 0.36, 0.6, XS[0] - 0.45, XS[5] + 0.45)
for (a, b, name) in [(0, 1, "Specialty Referral"), (2, 2, "Test Ordering"), (3, 3, "Examination"),
                     (4, 4, "Diagnosis"), (5, 5, "Treatment")]:
    txt((XS[a] + XS[b]) / 2, y + 0.53, name, bold=True)
hline(y + 0.68, 0.6, XS[0] - 0.4, XS[1] + 0.4)           # cmidrule under Specialty Referral
for j, m in enumerate(["Acc. (Lv1)", "IoU (Lv2)", "IoU", "DocLens", "LLM-judge", "IoU"]):
    txt(XS[j], y + 0.82, m, bold=True)
txt(X_CAT, y + 0.5, "Category", bold=True, ha="left"); txt(X_METH, y + 0.5, "Methods", bold=True, ha="left")
txt(XS[6], y + 0.5, "Average", bold=True)
y += top_h; hline(y, 0.9)                                 # midrule

for gi, (cat, rows) in enumerate(groups):
    y += 0.12
    y0 = y
    ours_group = gi == len(groups) - 1
    for name, vals in rows:
        y += row_h
        is_ca = name.startswith("ClinicalAgents")
        txt(X_METH, y - row_h / 2, name, ha="left", bold=is_ca, italic=ours_group)
        for j, v in enumerate(vals):
            b = (not ours_group) and v is not None and abs(v - best[j]) < 1e-9
            txt(XS[j], y - row_h / 2, fmt(v), bold=b, italic=ours_group)
    txt(X_CAT, (y0 + y) / 2, cat, bold=True, ha="left")
    y += 0.12
    hline(y, 1.4 if gi == len(groups) - 1 else 0.6)      # group separator / bottomrule

plt.savefig("medchain_table.png", bbox_inches="tight", facecolor="white"); plt.close()

# ------------------------------------------------------------------ LaTeX (booktabs)
tex = [r"% \usepackage{booktabs,multirow}", r"\begin{table*}[t]\centering\small",
       r"\caption{Overall results on the MedChain benchmark. Bold marks the best published value; "
       r"the last row is this study's pilot run.}",
       r"\begin{tabular}{llccccccc}\toprule",
       r"\multirow{3}{*}{\textbf{Category}} & \multirow{3}{*}{\textbf{Methods}} & \multicolumn{6}{c}{\textbf{MedChain}} & \multirow{3}{*}{\textbf{Average}}\\",
       r"\cmidrule(lr){3-8}",
       r" & & \multicolumn{2}{c}{\textbf{Specialty Referral}} & \textbf{Test Ordering} & \textbf{Examination} & \textbf{Diagnosis} & \textbf{Treatment} & \\",
       r"\cmidrule(lr){3-4}",
       r" & & Acc. (Lv1) & IoU (Lv2) & IoU & DocLens & LLM-judge & IoU & \\ \midrule"]
for gi, (cat, rows) in enumerate(groups):
    ours_group = gi == len(groups) - 1
    for ri, (name, vals) in enumerate(rows):
        c = (r"\multirow{%d}{*}{\textbf{%s}}" % (len(rows), cat)) if ri == 0 else ""
        cells = []
        for j, v in enumerate(vals):
            s = "--" if v is None else f"{v:.4f}"
            if not ours_group and v is not None and abs(v - best[j]) < 1e-9: s = r"\textbf{%s}" % s
            if ours_group: s = r"\textit{%s}" % s
            cells.append(s)
        tex.append(f"{c} & {name} & " + " & ".join(cells) + r" \\")
    tex.append(r"\bottomrule" if gi == len(groups) - 1 else r"\midrule")
tex += [r"\end{tabular}", r"\end{table*}"]
open("medchain_table.tex", "w").write("\n".join(tex))

print("this study:", [fmt(v) for v in ours])
print("saved medchain_table.png and medchain_table.tex")
